
create extension if not exists vector;

drop table if exists report_parts cascade;
drop table if exists reports cascade;
drop table if exists parts cascade;
drop table if exists vehicles cascade;
drop table if exists departments cascade;

create table departments (
  id serial primary key,
  name text not null unique,
  vehicle_type text not null,
  description text
);

create table vehicles (
  id serial primary key,
  car_no text not null unique,
  vehicle_type text not null,
  model text,
  built_year int,
  department_id int references departments(id)
);

create table parts (
  id serial primary key,
  name text not null unique,
  device text not null,
  replace_cycle_months int
);

create table reports (
  id serial primary key,
  report_no text not null unique,
  department_id int references departments(id),
  vehicle_id int references vehicles(id),
  occurred_at date not null,
  found_place text,
  found_stage text,
  writer text,
  device text not null,
  title text not null,
  symptom text not null,
  symptom_std text,
  cause text,
  action text,
  work_hours numeric,
  test_result text,
  service_impact text,
  prevention text,
  note text,
  status text not null default '확정',
  created_at timestamptz not null default now(),
  embedding vector(768)
);

create table report_parts (
  report_id int references reports(id) on delete cascade,
  part_id int references parts(id),
  qty int not null default 1,
  primary key (report_id, part_id)
);

create index reports_occurred_idx on reports (occurred_at desc);
create index reports_dept_idx on reports (department_id);
create index reports_vehicle_idx on reports (vehicle_id);

alter table departments enable row level security;
alter table vehicles enable row level security;
alter table parts enable row level security;
alter table reports enable row level security;
alter table report_parts enable row level security;

create or replace function match_reports(query_embedding vector(768), match_count int default 10)
returns table (id int, similarity float)
language sql stable
as $$
  select r.id, 1 - (r.embedding <=> query_embedding) as similarity
  from reports r
  where r.embedding is not null
  order by r.embedding <=> query_embedding
  limit match_count;
$$;

