insert into reports (report_no, department_id, vehicle_id, occurred_at, found_place, found_stage, writer, device, title, symptom, symptom_std, cause, action, work_hours, test_result, service_impact, prevention, note)
select s.no, s.dept, s.vid, s.d,
  (case t.vt when '전기기관차' then array['전기차량 검수고','입고 검사장','시운전선'] when '디젤기관차' then array['디젤차량 검수고','엔진 정비장','입고 검사장'] when '객차' then array['객차 검수고','도장·내장 작업장','입고 검사장'] else array['화차 검수고','대차 정비장','입고 검사장'] end)[s.pl],
  (array['입고 검사','중정비 작업 중','출고 전 시운전','운행 중 고장 입고'])[s.st],
  d.name || ' ' || (array['정비1팀','정비2팀','정비3팀','검사팀'])[s.wr],
  t.device, t.title, t.syms[s.sv], t.std, t.cause, t.action, t.hours + s.dh, '조치 후 동작 시험 정상', t.impact, t.prev, '가상 데이터'
from seed s join tpl t on t.id = s.tid join departments d on d.id = s.dept order by s.d;
insert into report_parts (report_id, part_id, qty)
select r.id, p.id, (e.value)::int from seed s join tpl t on t.id = s.tid join reports r on r.report_no = s.no
cross join lateral jsonb_each_text(t.parts) e join parts p on p.name = e.key;
select (select count(*) from reports) as reports, (select count(*) from vehicles) as vehicles, (select count(*) from parts) as parts, (select count(*) from report_parts) as report_parts;